    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; rects=[]
    import itertools
    for y in range(H):
        for x in range(W):
            if g[y][x]==v and not seen[y][x]:
                # try max rect anchored here with value v
                # extend right while all v
                w=1
                while x+w<W and all(g[y][x+w]==v for w in range(w)): pass
                rects.append((y,x,w,0))  # placeholder, fix below
    return rects
