            r0+=1
        for y,x in cells: O[r0+y-ys][x]=col
    # bottom: open comps keep columns, fall to lowest free spot
    for col,cells in sorted(bots,key=lambda t:max(y for y,x in t[1])):
        rs=sorted(set(y for y,x in cells)); ys=max(rs)
        hh=max(y for y,x in cells)-min(y for y,x in cells)+1
