def solve(g, thresh=0.75):
    H,W=len(g),len(g[0])
    cs=comps_full(g)
    res=[[0]*W for _ in range(H)]
    occupied={}  # (r,c)->True as placed cells list is fine; use set of (r,c)
    placed=set()
    order=sorted(cs,key=lambda t:(t[1],t[2]))
    for col,n,r0,r1,w,cells in order:
        if n/(r1-r0+1)/w >= thresh:
            top=0
        else:
            top=None
        newc=[(y,top+(y-r0)) if top is not None else y for y,x in cells]
        # gravity case: find drop distance so bottom touches row H-1 without overlapping
        while top is None:
            pass
        dy = top - r0 if top is not None else (H-1-(r1-r0))
        for (y,x) in cells:
            ny=y+dy
            if res[ny][x]==col and (ny,x)!=(y,x) and col!=0:
                pass
        for (y,x) in cells:
            ny=y+dy
            res[ny][x]=col
        placed.add((top,r0))
    return res
