# Try simulation: process comps ONE BY ONE in some order; each slides vertically (up or down) maximally without colliding with ALREADY PLACED comps; placed comps are fixed.
def simulate(cin, order, side, H, W):
    placed=[]
    for ci,(c,cells) in enumerate(cin):
        cur=[(a,b) for a,b in cells]
        if side=='up':
            while True:
                nxt=[(a-1,b) for a,b in cur]
                if all(a>=0 and (a,b) not in {(p[0],p[1]) for p in placed} for a,b in nxt):
                    cur=nxt
                else: break
        else:
            while True:
                nxt=[(a+1,b) for a,b in cur]
                if all(a<H and (a,b) not in {(p[0],p[1]) for p in placed} for a,b in nxt):
                    cur=nxt
                else: break
        placed.append(cur)
    # reconstruct grid
    grid=[[0]*W for _ in range(H)]
    for c,cells in zip([x[0] for x in cin],placed):
        for a,b in cells: grid[a][b]=c
    return grid
