# Verify rule: frame (comp adjacent to an enclosed background hole) -> slide up until blocked; solid -> slide down.
def solve(g):
    H,W=len(g),len(g[0])
    bg=collections.Counter(x for r in g for x in r).most_common(1)[0][0]
    # holes: bg cells not reachable from border through bg cells
    from collections import deque
    reach=[[False]*W for _ in range(H)]; dq=deque()
    for a in range(H):
        for b in range(W):
            if (a in(0,H-1) or b in(0,W-1)) and g[a][b]==bg and not reach[a][b]:
                reach[a][b]=True; dq.append((a,b))
    while dq:
        x,y=dq.popleft()
        for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
            nx,ny=x+dx,y+dy
            if 0<=nx<H and 0<=ny<W and g[nx][ny]==bg and not reach[nx][ny]:
                reach[nx][ny]=True; dq.append((nx,ny))
    holes={(a,b) for a in range(H) for b in range(W) if g[a][b]==bg and not reach[a][b]}
    cs=cc(g)
    def frame(cells):
        return any((r,c) in holes for r,c in cells)
    grid=[row[:] for row in g]
    changed=True
    while changed:
        changed=False
        for col,S in cs:
            cells=set(S)
            isf=frame(cells)
            dirs = [(-1,0)] if isf else [(1,0)]
            for dr,dc in dirs:
                # how far can it slide?
                steps=0
                while True:
                    newc={(r+dr*(steps+1),c+dc*(steps+1)) for r,c in cells}
                    ok=all(0<=r<H and 0<=c<W and (grid[r][c]==bg or (r,c) in cells) for r,c in newc)
                    if not ok: break
                    steps+=1
                d=steps if steps>0 else 0
                if d>0:
                    for r,c in cells: grid[r][c]=bg
                    for r,c in cells: grid[r+d*dr][c+d*dc]=col
                    changed=True
    return grid
