G=load(); g=G['Test input']
H,W=len(g),len(g[0])
from collections import deque
vis=[[False]*W for _ in range(H)]; dq=deque()
for i in range(H):
    for j in range(W):
        if g[i][j]!=0 and i*H+j==0: continue
# simpler: seed zero-components; find components not reaching border via BFS
seed=set()
for i in range(H):
    for j in range(W):
        if g[i][j]==0: seed.add((i,j))
# remove border-reachable zeros: BFS over zeros avoiding edges... use border seeds
bq=[]
for i in range(H):
    for j in range(W):
        if g[i][j]==0 and (i in(0,H-1) or j in(0,W-1)): bq.append((i,j)); vis[i][j]=True
while bq:
