    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
        ni,nj=i+di,j+dj
        if 0<=ni<H and 0<=nj<W and g[ni][nj]==0 and not vis[ni][nj]:
            vis[ni][nj]=True; bq.append((ni,nj))
out=[row[:] for row in g]
unpainted=[(i,j) for i in range(H) for j in range(W) if g[i][j]==0 and not vis[i][j]]
seen=set()
for (i,j) in unpainted:
