            if 0<=ni<H and 0<=nj<W and g[ni][nj]==0 and (ni,nj) not in seen: stack.append((ni,nj))
    # neighbor colors among original
    nbs={g[a][b] for c,b in comp for a,b in [(c+1,b),(c-1,b),(c,b+1),(c,b-1)] if 0<=a<H and 0<=b<W and g[a][b]!=0}
