from collections import deque
def solve(g):
    H,W=len(g),len(g[0])
    # BFS from border over zeros -> reachable set
    vis=set(); dq=deque()
    for i in range(H):
        for j in (0,W-1):
            if g[i][j]==0 and (i,j) not in vis: vis.add((i,j)); dq.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if g[i][j]==0 and (i,j) not in vis: vis.add((i,j)); dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and g[ni][nj]==0 and (ni,nj) not in vis:
                vis.add((ni,nj)); dq.append((ni,nj))
    out=[r[:] for r in g]
    seen=set()
    for i in range(H):
        for j in range(W):
            if g[i][j]==0 and (i,j) not in vis:
                stack=[(i,j)]; comp=[]
                while stack:
                    c,b=stack.pop()
                    if (c,b) in seen: continue
                    seen.add((c,b)); comp.append((c,b))
                    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        ni,nj=c+di,b+dj
                        if 0<=ni<H and 0<=nj<W and g[ni][nj]==0 and (ni,nj) not in seen:
