                nbs={g[a][b] for c,b in comp for a,b in [(c+1,b),(c-1,b),(c,b+1),(c,b-1)] if 0<=a<H and 0<=b<W and g[a][b]!=0}
                col=nbs.pop()
                for c,b in comp: out[c][b]=col
    return out
