import collections
gi,go=G['Demo pair 0 input'],G['Demo pair 0 output']
def f(g):
    g=[r[:] for r in g]
    seen=set(); q=collections.deque()
    for i,r0 in enumerate(g):
        for j,x in enumerate(r0):
            if x!=0 or (i==0 or j==0 or i==len(g)-1 or j==len(g[0])-1): continue
            if (i,j) not in seen: q.append((i,j)); seen.add((i,j))
    while q:
        i,j=q.popleft()
        nb=[(i+1,j),(i-1,j),(i,j+1),(i,j-1)]
        for di,dj in nb:
            if 0<=di<len(g) and 0<=dj<len(g[0]) and (di,dj) not in seen and g[di][dj]==0:
                seen.add((di,dj)); q.append((di,dj))
    return [(r[0],r[-1]) for r in [[g[i][j] for j in range(len(g[0]))] for i in range(len(g))]]
